async function method(name,args){return (await request('/api/method/'+name+'?'+new URLSearchParams(args))).message;}
function table(headers,rows){return '<div class="cl-table-wrap"><table><thead><tr>'+headers.map(x=>'<th>'+x+'</th>').join('')+'</tr></thead><tbody>'+rows.map(r=>'<tr>'+r.map((x,i)=>'<td data-label="'+esc(headers[i])+'">'+x+'</td>').join('')+'</tr>').join('')+'</tbody></table></div>';}
function unavailable(id){put(id,'<p class="cl-empty">This source is unavailable. Refresh to retry; no zero values have been assumed.</p>');}
function mask(v){return v?'••••••'+esc(String(v).slice(-4)):'—';}
