function enhanceTables(root){root.querySelectorAll('.cl-table-wrap').forEach(w=>{const rows=[...w.querySelectorAll('tbody tr')];if(rows.length&& !rows.some(r=>/^(GRAND TOTAL|CLUSTER TOTAL)/.test(r.textContent))&&w.closest('#cl-recovery,#cl-media,#cl-execution,#cl-approvals')){const head=[...w.querySelectorAll('th')].map(x=>x.textContent),tr=document.createElement('tr');tr.className='cl-total';tr.innerHTML=head.map((h,i)=>{if(i===0)return '<td>GRAND TOTAL</td>';const vals=rows.map(r=>r.children[i]?.textContent.trim()||'');if(/share/i.test(h))return '<td>100%</td>';if(vals.every(v=>/^(₹\s*)?[\d,]+$/.test(v))){const n=vals.reduce((s,v)=>s+Number(v.replace(/[^\d.-]/g,'')),0);return '<td>'+(vals.some(v=>v.includes('₹'))?money(n):n)+'</td>';}return '<td>—</td>';}).join('');w.querySelector('tbody').append(tr);}if(rows.length>15){rows.forEach((r,i)=>r.hidden=i>=15);const b=document.createElement('button');b.className='cl-more';b.textContent='Load 15 more · Showing 15 of '+rows.length;b.onclick=()=>{const shown=rows.filter(r=>!r.hidden).length;rows.slice(shown,shown+15).forEach(r=>r.hidden=false);const count=Math.min(shown+15,rows.length);b.textContent=count===rows.length?'All '+count+' rows shown':'Load 15 more · Showing '+count+' of '+rows.length;b.disabled=count===rows.length;w.scrollTop=Math.max(0,rows[shown].getBoundingClientRect().top-w.getBoundingClientRect().top+w.scrollTop-45);};w.after(b);}});root.querySelectorAll('tbody tr').forEach(row=>{const cells=[...row.children];if(/^(GRAND TOTAL|CLUSTER TOTAL)/.test(row.textContent))row.classList.add('cl-total');cells.forEach(td=>{const v=td.textContent.trim();if(/^₹\s*[\d,]+/.test(v)||/^\d+$/.test(v)){const n=Number(v.replace(/[^\d.-]/g,''));td.style.color=n>0?'#176d43':'#64706c';}});const abs=[...row.querySelectorAll('[data-absent]')],max=Math.max(0,...abs.map(x=>+x.dataset.absent));abs.forEach(x=>{if(max>0&&+x.dataset.absent===max)x.closest('.cl-absence').classList.add('cl-worst');});});}
function setupSections(){const d=dates();$('cl-compare-from').value=d.from;$('cl-compare-to').value=d.today;const change=()=>{const range=$('cl-compare-mode').value==='range';$('cl-compare-from').hidden=$('cl-compare-to').hidden=!range;if(!range)compareLoad();};$('cl-compare-mode').onchange=change;$('cl-compare-apply').onclick=compareLoad;change();const sections=[...document.querySelectorAll('#cl-overview > section')];for(const section of sections){const head=section.querySelector('.cl-panel-title,.bcc-panel-head');if(!head)continue;const bar=document.createElement('div');bar.className='cl-section-tools';for(const [label,action]of [['↑',()=>{const prev=section.previousElementSibling;if(prev?.matches('section'))section.parentNode.insertBefore(section,prev);saveOrder();}],['↓',()=>{const next=section.nextElementSibling;if(next?.matches('section'))section.parentNode.insertBefore(next,section);saveOrder();}],['Print',()=>{document.body.classList.add('cl-printing');section.classList.add('cl-print-target');window.print();section.classList.remove('cl-print-target');document.body.classList.remove('cl-printing');}]]){const b=document.createElement('button');b.textContent=label;b.title=label==='Print'?'Print this section':label==='↑'?'Move section up':'Move section down';b.onclick=action;bar.append(b);}head.append(bar);}try{const order=JSON.parse(localStorage.getItem('life-cluster-section-order')||'[]');const anchor=$('cl-overview').querySelector(':scope > .cl-footnote');order.forEach(id=>{const s=$(id);if(sections.includes(s))anchor.before(s);});}catch(e){} }
function saveOrder(){try{localStorage.setItem('life-cluster-section-order',JSON.stringify([...document.querySelectorAll('#cl-overview > section')].map(s=>s.id)));}catch(e){}}

function fail(e){S.loading=null;$('cl-status').textContent=e.message||'Unable to load cluster data. Please refresh.';$('cl-refresh').disabled=false;}
